// Cloudflare Worker: strip unkeyed headers
addEventListener('fetch', event => {
  const request = new Request(event.request);
  // Remove headers that affect response but aren't in cache key
  request.headers.delete('X-Forwarded-Host');
  request.headers.delete('X-Original-URL');
  event.respondWith(fetch(request));
});

export async function GET(req: Request, { params }: { params: { id: string } }) {
  const session = await requireAuth(req);
  const invoice = await db.invoice.findUnique({ where: { id: params.id } });
  if (!invoice) return new Response('Not Found', { status: 404 });
  // Critical: verify the requester owns this resource
  if (invoice.userId !== session.userId && session.role !== 'admin') {
    return new Response('Forbidden', { status: 403 });
  }
  return Response.json(invoice);
}

const ALLOWED_HOSTS = new Set(['yourdomain.com']);

function safeRedirectTarget(next: string): string {
  if (next.startsWith('/')) return next; // relative is always fine
  try {
    const parsed = new URL(next);
    if (ALLOWED_HOSTS.has(parsed.hostname)) return parsed.href;
  } catch {
    // fall through to default
  }
  return '/dashboard';
}

const ALLOWED_HOSTS = new Set(['yourdomain.com']);

function metaRefreshTarget(next: string): string {
  if (next.startsWith('/')) return next;
  try {
    const parsed = new URL(next);
    if (ALLOWED_HOSTS.has(parsed.hostname)) return parsed.href;
  } catch {}
  return '/';
}
